# Shell sheets: QuickSettings, CalendarSheet, Overview, Lock, Login.
from gen import *
W, H = 360, 225

begin('QuickSettings.dc.html')
def qt(icon, label, state_text, on, a, more=None):
    """Quick tile: the main part switches, the arrow part (only where a choice exists) opens the list."""
    bg = t.acc if on else t.raised; fg = t.onacc if on else t.text; bd = t.acctext if on else t.ctl
    m = f'<button{act(more, label + ": " + L("اختيار", "choose"))} aria-label="{plain(label)}: {L("اختيار", "choose")}" aria-haspopup="dialog" style="width: {tgt}; align-self: stretch; display: inline-flex; align-items: center; justify-content: center; border-inline-start: {HAIR} solid {bd}">{ic("forward", True)}</button>' if more else ''
    return f'<div style="height: {bar_h}; border-radius: {r_card}; background: {bg}; color: {fg}; border: {HAIR} solid {bd}; box-sizing: border-box; display: flex; overflow: hidden"><button role="switch" aria-checked="{"true" if on else "false"}"{act(a, label)} aria-label="{plain(label)}: {plain(state_text)}" style="flex: 1; min-width: 0; display: flex; align-items: center; gap: {s3}; padding: 0 {s3}"><span style="display: inline-flex">{ic(icon)}</span><span style="display: block; min-width: 0"><span style="display: block; font-weight: {w6}">{tx(label)}</span><span style="display: block; font-size: {f12}">{tx(state_text)}</span></span></button>{m}</div>'
OFF, MOFF, ON = 'مُطفأ', 'غير مفعّل', 'مفعّل'
tiles = f'<div style="display: grid; grid-template-columns: 1fr 1fr; gap: {s2}">' + qt('wifi', 'واي فاي', 'KM-Office', True, 'qs.wifi', 'qs.wifi.list') + qt('cable', 'الشبكة السلكية', 'متصلة · 1 Gbit/s', True, 'qs.wired') \
    + qt('bluetooth', 'بلوتوث', OFF, False, 'qs.bluetooth', 'qs.bluetooth.list') + qt('plane', 'وضع الطيران', MOFF, False, 'qs.toggle') \
    + qt('vpn', 'VPN', OFF, False, 'qs.vpn', 'qs.vpn.list') + qt('moon', 'الضوء الليلي', 'حتى 06:10', True, 'qs.toggle') \
    + qt('contrast', 'الوضع الداكن', ON, True, 'qs.toggle') + qt('bell-off', 'عدم الإزعاج', MOFF, False, 'qs.toggle') \
    + qt('battery', 'وضع الطاقة', 'متوازن', True, 'qs.powermode', 'qs.powermode.list') + qt('mesh', 'الترابط', 'جهازان', True, 'qs.mesh', 'qs.mesh.list') + '</div>'
vol = f'<div style="display: flex; align-items: center; gap: {s2}">{slider("مستوى الصوت", 62, "qs.volume", icon="volume")}{ibtn("جهاز إخراج الصوت: مكبّرات الصوت", "speaker", "qs.output")}</div>'
bri = f'<div style="display: flex; align-items: center; gap: {s2}">{slider("السطوع", 78, "qs.brightness", icon="sun")}<span style="width: {tgt}"></span></div>'
foot = f'<div style="display: flex; align-items: center; justify-content: space-between; padding-top: {s3}; border-top: {HAIR} solid {t.line}"><button{act("qs.battery", "البطارية 87% · متوازن")} aria-label="البطارية 87% · متوازن" style="height: {tgt}; padding: 0 {s2}; border-radius: {r_ctl}; display: inline-flex; align-items: center; gap: {s2}">{ic("battery", True)}<span>{tx("87% · متوازن")}</span></button><div style="display: flex; gap: {s1}">{ibtn("المساعد", "spark", "qs.assistant")}{ibtn("لقطة شاشة", "shot", "qs.shot")}{ibtn("الإعدادات", "gear", "qs.settings")}{ibtn("قفل", "lock", "qs.lock")}{ibtn("خيارات الطاقة", "power", "qs.power")}</div></div>'
# focus order: the open sheet first, then the bar (A33)
out('Ultar OS – الإعدادات السريعة', W, H, sheet('الإعدادات السريعة', tiles + vol + bri + foot, 112) + bottombar(open_='quick'), 'Schnelleinstellungen', 1)

begin('CalendarSheet.dc.html')
def notif(icon, app, title, text, when, actions):
    return f'<li style="border-radius: {r_card}; background: {t.raised}; border: {HAIR} solid {t.line}; padding: {s3}; display: flex; gap: {s3}"><span style="display: inline-flex; color: {t.mute}">{ic(icon)}</span><div style="flex: 1; min-width: 0"><div style="display: flex; justify-content: space-between; font-size: {f12}; color: {t.mute}"><span>{tx(app)}</span><span>{ltr(when)}</span></div><div style="font-weight: {w6}">{tx(title)}</div><div style="font-size: {f12}; color: {t.mute}">{tx(text)}</div><div style="display: flex; gap: {s2}; padding-top: {s2}">{actions}</div></div>{ibtn("إخفاء الإشعار: " + title, "close", "note.dismiss")}</li>'
notes = f'<div style="flex: 1; min-width: 0; display: flex; flex-direction: column; gap: {s3}"><div style="display: flex; align-items: center; gap: {s3}">{h2("الإشعارات")}<span style="flex: 1"></span><span style="font-size: {f12}; color: {t.mute}">عدم الإزعاج</span>{switch(False, "عدم الإزعاج", "note.dnd")}{button("مسح الكل", "note.clear", "quiet")}</div><ul role="list" style="display: flex; flex-direction: column; gap: {s2}">' \
    + notif('update', 'التحديثات', 'تحديث النظام جاهز', 'يُثبَّت عند إعادة التشغيل التالية.', '16:40', button('إعادة التشغيل الآن', 'note.action', name='تحديث النظام: إعادة التشغيل الآن') + button('لاحقاً', 'note.action', 'quiet', name='تحديث النظام: لاحقاً')) \
    + notif('folder', 'الملفات', 'تم توصيل ذاكرة USB', 'جاهزة للاستخدام.', '16:31', button('فتح', 'note.action', name='ذاكرة USB: فتح') + button('إخراج', 'note.action', name='ذاكرة USB: إخراج')) \
    + notif('bag', 'متجر Ultar', 'اكتمل تثبيت «الجداول»', 'من مكوّن الأدوات المكتبية.', '15:02', button('فتح', 'note.action', name='الجداول: فتح')) + '</ul></div>'
days = [('س', 'السبت'), ('ح', 'الأحد'), ('ن', 'الاثنين'), ('ث', 'الثلاثاء'), ('ر', 'الأربعاء'), ('خ', 'الخميس'), ('ج', 'الجمعة')]
head = '<div role="row" style="display: contents">' + ''.join(f'<div role="columnheader" aria-label="{n}" style="height: {tgt}; display: flex; align-items: center; justify-content: center; font-size: {f12}; color: {t.mute}">{d}</div>' for d, n in days) + '</div>'
cells = ''
for i in range(35):
    num = 31 if i == 0 else (i if i <= 30 else i - 30); cur = 1 <= i <= 30; today = i == 22
    month = 'تشرين الثاني' if cur else ('تشرين الأول' if i == 0 else 'كانون الأول')
    if i % 7 == 0: cells += '<div role="row" style="display: contents">'
    cells += f'<button role="gridcell"{act("cal.day", f"{num} {month}")} aria-label="{num} {month}{" (اليوم)" if today else ""}"{" aria-current=\"date\"" if today else ""}{"" if today else " tabindex=\"-1\""} style="height: {tgt}; border-radius: {r_ctl}; display: flex; align-items: center; justify-content: center; background: {t.acc if today else "transparent"}; border: {HAIR} solid {t.acctext if today else "transparent"}; box-sizing: border-box; color: {t.onacc if today else (t.text if cur else t.mute)}; font-weight: {w7 if today else w4}">{num}</button>'
    if i % 7 == 6: cells += '</div>'
events = f'<div style="display: flex; flex-direction: column; gap: {s1}">{h2("مواعيد اليوم", f14)}' + ''.join(f'<button{act("cal.event", title)} style="height: {tgt}; padding: 0 {s2}; border-radius: {r_ctl}; display: flex; align-items: center; gap: {s3}"><span style="color: {t.mute}; font-size: {f12}">{ltr(when)}</span><span>{tx(title)}</span></button>' for when, title in (('17:30', 'اجتماع فريق التصميم'), ('20:00', 'موعد طبيب الأسنان'))) + '</div>'
cal = f'<div style="width: {g(64)}; flex: none; display: flex; flex-direction: column; gap: {s3}"><div style="display: flex; align-items: center; gap: {s1}"><div style="flex: 1">{h2("تشرين الثاني 2026")}{sub("جمادى الآخرة 1448")}</div>{ibtn("الشهر السابق", "back", "cal.month")}{ibtn("الشهر التالي", "forward", "cal.month")}</div><div role="grid" aria-label="تشرين الثاني 2026" style="display: grid; grid-template-columns: repeat(7, 1fr); gap: {s1}">{head}{cells}</div>{events}</div>'
out('Ultar OS – التقويم والإشعارات', W, H, sheet('التقويم والإشعارات', f'<div style="display: flex; gap: {s5}">{notes}{cal}</div>', 184) + bottombar(open_='calendar'), 'Kalender und Benachrichtigungen (Klick auf die Uhr)', 1)

begin('Overview.dc.html')
def ws(n, wins, current=False, empty_=False):
    mini = ''.join(f'<span style="width: {g(w)}; height: {g(h)}; border-radius: {r_ctl}; background: {t.raised}; border: {HAIR} solid {t.ctl}; box-sizing: border-box"></span>' for w, h in wins)
    label = 'مساحة عمل جديدة' if empty_ else f'مساحة العمل {n}'
    return f'<button{act("overview.workspace", label)} aria-label="{label}"{" aria-current=\"true\"" if current else ""} style="width: {g(48)}; display: flex; flex-direction: column; gap: {s1}; align-items: center"><span style="width: 100%; height: {g(24)}; border-radius: {r_ctl}; background: {t.surface}; border: {RING if current else HAIR} solid {t.acctext if current else t.ctl}; box-sizing: border-box; display: flex; align-items: center; justify-content: center; gap: {s1}">{mini if not empty_ else ic("plus")}</span><span style="font-size: {f12}; font-weight: {w6 if current else w4}; display: inline-flex; align-items: center; gap: {s1}">{ic("check", True) if current else ""}{tx(label)}</span></button>'
strip = f'<div style="display: flex; justify-content: center; gap: {s4}">{ws(1, ((16, 12), (10, 8), (12, 10)), True)}{ws(2, ((20, 14),))}{ws(3, (), empty_=True)}</div>'
def preview(icon, title, w, h):
    return f'<div style="position: relative; width: {g(w)}"><button{act("overview.window", title)} aria-label="{plain(title)}" style="width: 100%; display: flex; flex-direction: column; gap: {s2}"><span style="width: 100%; height: {g(h)}; border-radius: {r_card}; background: {t.surface}; border: {HAIR} solid {t.ctl}; box-sizing: border-box; box-shadow: {t.shadow}; display: flex; flex-direction: column; overflow: hidden"><span style="height: {s5}; background: {t.bar}; border-bottom: {HAIR} solid {t.line}"></span><span style="flex: 1; display: flex; align-items: center; justify-content: center; color: {t.mute}">{ic(icon)}</span></span><span style="display: flex; align-items: center; justify-content: center; gap: {s2}; font-weight: {w6}">{ic(icon, True)}{tx(title)}</span></button><span style="position: absolute; top: {s1}; inset-inline-end: {s1}">{ibtn("إغلاق النافذة: " + title, "close", "overview.close")}</span></div>'
wins = f'<div style="flex: 1; display: flex; align-items: center; justify-content: center; gap: {s6}">{preview("folder", "الملفات – المستندات", 112, 72)}{preview("terminal", "الطرفية", 80, 48)}{preview("gear", "الإعدادات – الشاشات", 96, 64)}</div>'
top = f'<div style="display: flex; justify-content: center">{searchbox("اكتب للبحث في التطبيقات والإعدادات والملفات", "overview.search", width=g(140))}</div>'
out('Ultar OS – نظرة عامة', W, H, f'<main aria-label="نظرة عامة" style="position: absolute; inset-inline: 0; top: 0; bottom: {bar_h}; padding: {s5} {s7}; box-sizing: border-box; display: flex; flex-direction: column; gap: {s5}">{top}{strip}{wins}</main>' + bottombar(running=(('files', 1), ('terminal', 1), ('settings', 1)), open_='overview'), 'Übersicht: Suchfeld, Arbeitsflächen-Streifen, Fenster (§5.1)', 1)

begin('Lock.dc.html')
status = f'<div aria-label="الحالة" style="position: absolute; top: {s4}; inset-inline-end: {s5}; display: flex; gap: {s3}; color: {t.mute}">{ic("wifi", True)}{ic("battery", True)}</div>'
clock = f'<div style="text-align: center"><div role="timer" style="font-family: {FF_TITLE}; font-size: {f32}; font-weight: {w7}">{ltr("16:52")}</div><div style="font-size: {f16}">{tx("الأحد 22 تشرين الثاني 2026")}</div>{sub("21 جمادى الآخرة 1448")}</div>'
def ln(icon, app, text):
    return f'<li style="width: {g(100)}; border-radius: {r_card}; background: {t.surface}; border: {HAIR} solid {t.line}; padding: {s3} {s4}; box-sizing: border-box; display: flex; align-items: center; gap: {s3}"><span style="display: inline-flex; color: {t.mute}">{ic(icon)}</span><div style="flex: 1"><div style="font-weight: {w6}">{tx(app)}</div>{sub(text)}</div></li>'
lnotes = f'<ul role="list" aria-label="الإشعارات" style="display: flex; flex-direction: column; gap: {s2}">{ln("phone", "الهاتف", "مكالمة فائتة واحدة · المحتوى مخفي")}{ln("bag", "متجر Ultar", "إشعار واحد · المحتوى مخفي")}</ul>'
media = f'<section aria-label="التحكّم بالوسائط" style="width: {g(100)}; border-radius: {r_card}; background: {t.surface}; border: {HAIR} solid {t.line}; padding: {s3} {s4}; box-sizing: border-box; display: flex; align-items: center; gap: {s3}"><div style="flex: 1"><div style="font-weight: {w6}">يا مال الشام</div>{sub("صباح فخري")}</div>{ibtn("المقطع السابق", "prev", "lock.media")}{ibtn("تشغيل", "play", "lock.media")}{ibtn("المقطع التالي", "next", "lock.media")}</section>'
unlock = button('فتح القفل', 'lock.unlock', 'primary', icon='lock')
bottom = f'<div style="position: absolute; bottom: {s5}; inset-inline: {s5}; display: flex; justify-content: space-between">{button("طوارئ", "lock.sos", icon="sos")}{button("إيقاف التشغيل الطارئ", "lock.power", icon="power")}</div>'
out('Ultar OS – شاشة القفل', W, H, f'<main aria-label="شاشة القفل" style="position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: {s5}">{clock}{unlock}{lnotes}{media}</main>' + status + bottom, 'Sperrbildschirm (§5.3)', 1)

begin('Login.dc.html')
def user(name, on):
    return f'<button role="radio" aria-checked="{"true" if on else "false"}"{act("login.user", name)}{"" if on else " tabindex=\"-1\""} style="width: {g(40)}; padding: {s3}; box-sizing: border-box; border-radius: {r_card}; background: {t.hover if on else t.surface}; border: {RING if on else HAIR} solid {t.acctext if on else t.ctl}; display: flex; flex-direction: column; align-items: center; gap: {s2}"><span style="width: {s7}; height: {s7}; border-radius: {r_round}; background: {t.raised}; border: {HAIR} solid {t.ctl}; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center">{ic("user")}</span><span style="font-weight: {w6}; display: inline-flex; align-items: center; gap: {s1}">{ic("check", True) if on else ""}{name}</span></button>'
users = radiogroup('المستخدمون', user('أنس', True) + user('ليلى', False))
pw = f'<div style="width: {g(84)}; display: flex; align-items: flex-end; gap: {s2}">{field("كلمة مرور أنس", "login.password", kind="password", value="••••••••")}{ibtn("إظهار كلمة المرور", "eye", "login.show")}</div>'
alt = f'<div style="display: flex; gap: {s2}">{button("استخدام الرمز PIN", "login.method", "quiet")}</div>'
tools = f'<div style="position: absolute; bottom: {s5}; inset-inline: {s5}; display: flex; justify-content: flex-end; gap: {s2}">{kbd_button()}{ibtn("تسهيلات الاستخدام", "access", "login.access")}{ibtn("خيارات الطاقة", "power", "qs.power")}</div>'
out('Ultar OS – تسجيل الدخول', W, H, f'<main aria-label="تسجيل الدخول" style="position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: {s5}"><div style="display: flex; align-items: center; gap: {s3}">{mark()}<span style="font-family: {FF_TITLE}; font-size: {f24}; font-weight: {w7}">Ultar OS</span></div>{users}{pw}{button("تسجيل الدخول", "login.submit", "primary")}{alt}</main>' + tools, 'Anmeldebildschirm (§5.3)', 1)
